def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                cr, cc = stack.pop()
                comp.append((cr, cc))
                for nr, nc in ((cr-1, cc), (cr+1, cc), (cr, cc-1), (cr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == 5 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            r0 = min(x for x, _ in comp)
            r1 = max(x for x, _ in comp)
            c0 = min(y for _, y in comp)
            c1 = max(y for _, y in comp)

            top_cells = {cc for rr, cc in comp if rr == r0}
            gaps = [cc for cc in range(c0 + 1, c1) if cc not in top_cells]
            if len(gaps) != 1:
                continue
            gap = gaps[0]

            for rr in range(r0 + 1, r1):
                for cc in range(c0 + 1, c1):
                    if out[rr][cc] == 0:
                        out[rr][cc] = 2
            if out[r0][gap] == 0:
                out[r0][gap] = 2

            beam_row = r0 - 1
            if beam_row >= 0:
                if gap > (c0 + c1) / 2:
                    beam_cols = range(0, gap + 1)
                else:
                    beam_cols = range(gap, w)
                for cc in beam_cols:
                    if out[beam_row][cc] == 0:
                        out[beam_row][cc] = 2

    return out
